// 演示·集结号：unit.deployed → Host==载荷单位 → 从卡组抽 1 张牌。
Func<Orc.Cards.CardEventView, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Unit is not Orc.Cards.Card deployed || !object.ReferenceEquals(deployed, view.Host)) return;
    var runtime = Orc.Game.Effects.EffectRuntime.ResolveFor(deployed);
    if (runtime is null) return;
    await runtime.DrawAsync(deployed, 1, ct);
};
